// The licence agreement of LX Music+ (the same file in the desktop and the mobile app): the one of LX Music
// (lyswhut), for LX Music+ and its sources (none built in), in the language of the app

/** a part of a paragraph: text, bold text, a link (the licence of the app, its repository) */
export type PactPart = string | { bold: string } | { link: 'license' | 'repo', text: string }
export interface PactParagraph {
  heading?: boolean
  parts: PactPart[]
}
export interface PactText {
  title: string
  /** before it is accepted */
  mustAgree: string
  paragraphs: PactParagraph[]
  /** under it, before it is accepted */
  acceptTip: string
}

export interface PactApp {
  /** desktop / mobile */
  platform: 'desktop' | 'mobile'
  /** the licence of the app: AGPL (desktop), Apache (mobile) */
  license: 'agpl' | 'apache'
}

type Lang = 'en' | 'cn' | 'tw' | 'ja' | 'ko' | 'es' | 'pt' | 'ru' | 'vi' | 'de' | 'fr' | 'it' | 'pl'
const OTHER_LANGS: Lang[] = ['ja', 'ko', 'es', 'pt', 'ru', 'vi', 'de', 'fr', 'it', 'pl']
const getLang = (locale: string): Lang => {
  const value = locale.toLowerCase().replace('_', '-')
  if (/^zh-(tw|hk|hant)/.test(value)) return 'tw'
  if (value.startsWith('zh')) return 'cn'
  return OTHER_LANGS.find(lang => value.startsWith(lang)) ?? 'en'
}

