/**
 * The licence agreement in the language of the app (English for the languages it has not been translated to)
 */
export const getPactText = (locale: string, app: PactApp): PactText => {
  const lang = getLang(locale)
  return TEXTS[lang](LICENSE_NAMES[app.license][lang], PLATFORM_NAMES[app.platform][lang])
}
